CREATE OR REPLACE FUNCTION private.exam_get(_hw uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE h homework; p exam_papers; teacher boolean; BEGIN SELECT * INTO h FROM homework WHERE id=_hw; IF h.id IS NULL OR h.kind<>'test' OR NOT can_read_homework(_hw) THEN RAISE EXCEPTION 'غير مصرح' USING ERRCODE='42501'; END IF; teacher:=is_course_teacher(h.course_id); SELECT * INTO p FROM exam_papers WHERE homework_id=_hw; RETURN jsonb_build_object('can_edit',teacher AND h.status='draft','can_grade',teacher,'questions',coalesce((SELECT jsonb_agg(CASE WHEN teacher THEN q ELSE q-'correct'-'answer' END) FROM jsonb_array_elements(coalesce(p.questions,'[]')) q),'[]')); END $$;
DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('private._edu_manage(public.edu_records)'::regprocedure) INTO d; d:=replace(d,$old$_edu_ok(r.school_id,r.kind,'record') AND$old$, $new$(_edu_ok(r.school_id,r.kind,'record') OR _edu_ok(r.school_id,r.kind,'manage')) AND$new$); EXECUTE d;
SELECT pg_get_functiondef('private.edu_pool(uuid,text,text)'::regprocedure) INTO d; d:=replace(d,$old$IF NOT _edu_ok(_school,_kind,'record') THEN$old$,$new$IF NOT (_edu_ok(_school,_kind,'record') OR _edu_ok(_school,_kind,'manage')) THEN$new$); EXECUTE d;
SELECT pg_get_functiondef('private.edu_list(uuid,text,text,integer)'::regprocedure) INTO d; d:=replace(d,$old$'can_create',_edu_ok(_school,_kind,'record')$old$, $new$'can_create',(_edu_ok(_school,_kind,'record') OR _edu_ok(_school,_kind,'manage')) AND (_kind<>'case' OR is_org_owner(school_org(_school)) OR has_school_role(_school,ARRAY['counselor']::app_role[]) OR perm_allows(_school,'student_guidance','manage'))$new$); EXECUTE d;
END $$;